window.VO = [{"id":"n01","text":"You know the man with the mole.","at":0.24,"t0":0.12,"t1":1.485},{"id":"n02","text":"Last night, police picked up four of him.","at":3.57,"t0":1.785,"t1":3.905},{"id":"n03","text":"Only one is him, and you've seen all his crimes.","at":8.51,"t0":4.255,"t1":6.87},{"id":"n04","text":"Whoever you pick goes on every screen in the city tonight.","at":17.61,"t0":8.805,"t1":11.78},{"id":"n05","text":"So which one is him?","at":24.16,"t0":12.08,"t1":13.29},{"id":"n06","text":"Be sure.","at":29.66,"t0":14.83,"t1":15.565},{"id":"n07","text":"Because if it's the wrong man, that's an innocent man's face, everywhere he goes.","at":33.16,"t0":16.58,"t1":21.045},{"id":"n08","text":"And the real one walks right past it.","at":42.79,"t0":21.395,"t1":23.23},{"id":"n09","text":"And if you were right?","at":47.56,"t0":23.78,"t1":24.92},{"id":"t01","text":"Have you seen this man?","at":50.64,"t0":25.32,"t1":26.89},{"id":"n10","text":"Everyone's looking at his face.","at":54.58,"t0":27.29,"t1":28.915},{"id":"n11","text":"Nobody's looking at him.","at":58.43,"t0":29.215,"t1":30.575},{"id":"n12","text":"It was in every photo you saw.","at":65.95,"t0":32.975,"t1":34.645},{"id":"n13","text":"Memory keeps the mole, and drops the side.","at":70.29,"t0":35.145,"t1":37.575},{"id":"n14","text":"So be honest.","at":76.25,"t0":38.125,"t1":39.095},{"id":"n15","text":"Did you know it, or did you guess?","at":78.89,"t0":39.445,"t1":41.095}];
